<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\Auth;use App\Core\Request;use App\Core\Response;use App\Models\AuditLog;use App\Models\Post;use App\Services\CmsService;final class PostController extends AdminController{public function index(Request $e):Response{return $this->view('admin/posts/index',['posts'=>Post::all('id','DESC'),'meta'=>['title'=>t('admin.posts')]]);}public function edit(Request $c,?string $e=null):Response{$j=$e?Post::find((int)$e):null;return $this->view('admin/pages/edit',['item'=>$j,'kind'=>'post','blockTypes'=>CmsService::BLOCK_TYPES,'meta'=>['title'=>$j?t('common.edit'):t('common.create')]]);}public function save(Request $c):Response{if($s=$this->validate($c,['slug'=>'required|slug|max:191'],'/admin/posts')){return $s;}$b=$c->int('id');$G=['slug'=>$c->str('slug'),'title'=>$this->multilang($c->input('title')),'excerpt'=>$this->multilang($c->input('excerpt')),'blocks'=>CmsService::normalizeBlocks($c->input('blocks_json')),'cover'=>$c->str('cover')?CmsService::safeUrl($c->str('cover')):null,'tags'=>$c->str('tags')?:null,'is_published'=>$c->bool('is_published')?1:0,'published_at'=>$c->str('published_at')?gmdate('Y-m-d H:i:s',strtotime($c->str('published_at'))?:time()):now(),'author_id'=>Auth::id()];$w=Post::findBy('slug',$G['slug']);if($w&&(int)$w['id']!==$b){$this->flash('error',t('admin.slug_taken'));return $this->redirect($b?'/admin/posts/'.$b:'/admin/posts/create');}if($b){Post::update($b,$G);}else{$b=Post::create($G);}AuditLog::log('admin.post_save',$G['slug']);$this->flash('success',t('common.saved'));return $this->redirect('/admin/posts/'.$b);}public function delete(Request $e,string $i):Response{Post::delete((int)$i);AuditLog::log('admin.post_delete',$i);$this->flash('success',t('common.deleted'));return $this->redirect('/admin/posts');}}